const item = $input.first().json;

// Determine source — for now, always webhook. Email/Slack triggers added later.
const source = item.source || 'webhook';
const customer_id = item.email || item.customer_id || item.user_id || 'unknown';
const customer_name = item.name || item.customer_name || customer_id;
const message = item.message || item.text || item.body || '';
const subject = item.subject || '';
const timestamp = new Date().toISOString();
const thread_id = item.thread_id || item.threadId || '';
const is_reply = !!(item.is_reply || item.in_reply_to || thread_id);

return [{
  json: {
    source,
    customer_id,
    customer_name,
    message,
    subject,
    timestamp,
    thread_id,
    is_reply
  }
}];

// Pull data from previous nodes by name
const message = $('Normalize Message').first().json;
const kbEntries = $('Read Knowledge Base').all().map(i => i.json);
const configEntries = $('Read Agent Config').all().map(i => i.json);

// Build config lookup
const config = {};
for (const entry of configEntries) {
  config[entry.Setting] = entry.Value;
}

// Format KB entries for the prompt
const kbFormatted = kbEntries.map((entry, i) => {
  const id = entry.ID || (i + 1);
  return `[KB #${id}] Category: ${entry.Category}\nQuestion Patterns: ${entry['Question Pattern']}\nApproved Answer: ${entry['Approved Answer']}\nConfidence Override: ${entry['Confidence Threshold Override'] || 'default'}`;
}).join('\n\n');

const threshold = parseInt(config.confidence_threshold || '80');

const systemPrompt = `You are a customer support AI agent for ${config.business_name || '[Your Business Name]'}.

Your task: analyze the incoming customer message and determine the best response.

BUSINESS VOICE: ${config.business_voice || 'Professional but friendly. Use first names. Keep responses under 150 words.'}

KNOWLEDGE BASE:
${kbFormatted || '(No entries yet — all messages should go to human review)'}

ESCALATION KEYWORDS: ${config.escalation_keywords || 'urgent, refund, cancel, legal, lawyer, angry, furious, complaint, escalate'}

CONFIDENCE THRESHOLD: ${threshold} (auto-respond only when confidence >= this value)

INSTRUCTIONS:
1. First, check if the message contains any ESCALATION KEYWORDS. If yes, set action to "escalate" regardless of confidence.
2. Search the knowledge base for the best matching entry. Consider semantic meaning, not just keyword matching. "Where's my bill" matches "Invoice" entries. "Can't log in" matches "Password" entries.
3. Rate your confidence from 0-100:
   - 90-100: The knowledge base has an almost exact answer
   - 70-89: The knowledge base has a relevant answer but needs adaptation
   - 50-69: Partially related
   - 0-49: No match
4. Determine action:
   - If confidence >= ${threshold} and no escalation keywords: "auto_respond"
   - If confidence < ${threshold}: "needs_approval"
   - If escalation keywords found: "escalate"
5. Generate a response:
   - For auto_respond: Natural, personalized response based on the matched KB entry. Use the customer's name. Don't copy-paste — make it sound human.
   - For needs_approval: Your best attempt at a helpful response (will be reviewed by a human).
   - For escalate: Brief acknowledgment that the message has been flagged for the team.
6. Return ONLY valid JSON in this exact format:
{
  "classification": "[matched category from KB, or 'Unknown']",
  "confidence": [0-100],
  "action": "auto_respond" | "needs_approval" | "escalate",
  "matched_kb_id": [KB row ID or null],
  "response": "[the generated response text]",
  "reasoning": "[one sentence explaining why]",
  "detected_intent": "[what the customer actually wants]",
  "sentiment": "positive" | "neutral" | "frustrated" | "angry"
}`;

const userMessage = `From: ${message.customer_name} (${message.customer_id})\nSubject: ${message.subject || '(none)'}\nMessage: ${message.message}`;

return [{
  json: {
    systemPrompt,
    userMessage,
    confidence_threshold: threshold,
    config,
    original_message: message
  }
}];

const response = $input.first().json;
const context = $('Format Context for Claude').first().json;
const originalMessage = context.original_message;
const threshold = context.confidence_threshold || 80;

let parsed;
try {
  const text = response.content[0].text;
  const jsonMatch = text.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : text);
} catch (e) {
  parsed = {
    classification: 'Unknown',
    confidence: 0,
    action: 'needs_approval',
    matched_kb_id: null,
    response: "I apologize, but I wasn't able to process your request. A team member will assist you shortly.",
    reasoning: 'Failed to parse AI response: ' + e.message,
    detected_intent: 'unknown',
    sentiment: 'neutral'
  };
}

// Safety: override action if confidence below threshold
if (parsed.action === 'auto_respond' && parsed.confidence < threshold) {
  parsed.action = 'needs_approval';
  parsed.reasoning += ' (confidence below threshold, routing to human)';
}

return [{
  json: {
    ...parsed,
    source: originalMessage.source,
    customer_id: originalMessage.customer_id,
    customer_name: originalMessage.customer_name,
    message: originalMessage.message,
    subject: originalMessage.subject,
    timestamp: originalMessage.timestamp,
    thread_id: originalMessage.thread_id,
    is_reply: originalMessage.is_reply,
    config: context.config
  }
}];

const data = $input.first().json;
const signature = (data.config && data.config.welcome_signature) || 'Best regards, Support Team';

const formattedResponse = data.response + '\n\n' + signature;

return [{
  json: {
    // Fields matching Conversation Log sheet columns
    Timestamp: data.timestamp,
    'Source Channel': data.source,
    'Customer Identifier': data.customer_id,
    'Original Message': (data.message || '').substring(0, 500),
    'AI Classification': data.classification,
    'Confidence Score': data.confidence,
    'Action Taken': 'Auto-responded',
    'Response Sent': formattedResponse,
    'Response Source': 'Auto (KB #' + (data.matched_kb_id || 'AI') + ')',
    'Thread ID': data.thread_id || '',
    'Resolution Status': 'Resolved',
    'Time to Response': Math.floor((Date.now() - new Date(data.timestamp).getTime()) / 1000),
    // Keep these for downstream use
    formatted_response: formattedResponse,
    matched_kb_id: data.matched_kb_id,
    customer_name: data.customer_name,
    source: data.source,
    sentiment: data.sentiment,
    detected_intent: data.detected_intent,
    reasoning: data.reasoning
  }
}];
